import { getAuthUserId } from "@convex-dev/auth/server";
import { mutation, query } from "./_generated/server";
import { v } from "convex/values";
import type { Id } from "./_generated/dataModel";

const stores = [
  { name: "Blackpool North", shortName: "Blackpool" },
  { name: "Bolton", shortName: "Bolton" },
  { name: "Poulton-le-Fylde", shortName: "Poulton" },
  { name: "Rochdale", shortName: "Rochdale" },
];
const securityDefaults = ["Premises secure?", "Required security checks completed?", "Required security procedures understood and followed?"];
const openingDefaults = ["Food fridges operating correctly?", "Drinks fridges operating correctly?", "Food-preparation surfaces clean?", "Handwash soap available?", "Hot water available?", "Disposable hand-drying available?", "Food probe available and sanitised?", "Approved chemicals available?", "Allergen information available?", "Food correctly stored and labelled?", "No evidence of pest activity?", "Staff fit for work?"];
const closingDefaults = ["PM temperature checks completed?", "Expired or damaged food removed?", "Open food covered and labelled?", "Chilled food stored safely?", "Food-preparation areas cleaned?", "Equipment and utensils cleaned?", "Waste removed and bins controlled?", "Floors cleaned?", "Chemicals stored correctly?", "Outstanding issues handed over?"];
const equipmentCount = 4;
const wastageDefaults = ["Sausages", "Chicken Brioche", "Milk", "Bread"];
const cleaningDefaults = ["Food preparation surfaces", "Counters and service area", "Handles and touch points", "Floors", "Bins and waste area"];

function localDateKey(timestamp: number, timezone: string) { return new Intl.DateTimeFormat("en-CA", { timeZone: timezone, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(timestamp)); }
function localWeekday(timestamp: number, timezone: string) { const label = new Intl.DateTimeFormat("en-US", { timeZone: timezone, weekday: "short" }).format(new Date(timestamp)); return ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"].indexOf(label) + 1; }
async function signedIn(ctx: any) {
  const userId = await getAuthUserId(ctx);
  if (!userId) throw new Error("You must be signed in");
  return userId;
}
async function requireManager(ctx: any) {
  const userId = await signedIn(ctx);
  const user = await ctx.db.get(userId);
  const memberships = await ctx.db.query("memberships").withIndex("by_user", (q: any) => q.eq("userId", userId)).collect();
  const canManage = user?.role === "admin" || user?.role === "manager" || memberships.some((membership: any) => membership.role === "admin" || membership.role === "manager");
  if (!canManage) throw new Error("Manager access required");
  return userId;
}
async function seedLocation(ctx: any, locationId: Id<"locations">, userId: Id<"users">) {
  const existingTeamMembers = await ctx.db.query("teamMembers").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingTeamMembers.length) { const user = await ctx.db.get(userId); await ctx.db.insert("teamMembers", { locationId, name: user?.name || user?.email || "Team member", active: true, createdAt: Date.now() }); }
  const existingEquipment = await ctx.db.query("equipment").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingEquipment.length) for (let number = 1; number <= equipmentCount; number++) await ctx.db.insert("equipment", { locationId, name: `Fridge ${number}`, type: "Food fridge", preferredTemperature: 5, maximumTemperature: 8, order: number - 1, active: true });
  for (const session of ["AM", "PM"] as const) {
    const existing = await ctx.db.query("securityQuestions").withIndex("by_location_session", (q: any) => q.eq("locationId", locationId).eq("session", session)).collect();
    if (!existing.length) for (const [order, question] of securityDefaults.entries()) await ctx.db.insert("securityQuestions", { locationId, session, question, order, active: true });
  }
  for (const [checklist, defaults] of [["opening", openingDefaults], ["closing", closingDefaults]] as const) {
    const existing = await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", (q: any) => q.eq("locationId", locationId).eq("checklist", checklist)).collect();
    if (!existing.length) for (const [order, question] of defaults.entries()) await ctx.db.insert("checklistQuestions", { locationId, checklist, question, order, active: true });
  }
  const existingWastage = await ctx.db.query("wastageItems").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingWastage.length) for (const [order, name] of wastageDefaults.entries()) await ctx.db.insert("wastageItems", { locationId, name, order, active: true });
  const existingCleaning = await ctx.db.query("cleaningTasks").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
  if (!existingCleaning.length) for (const [order, name] of cleaningDefaults.entries()) await ctx.db.insert("cleaningTasks", { locationId, name, frequency: "daily", weekdays: [], order, active: true });
}

export const initializeDemo = mutation({
  args: {},
  handler: async (ctx) => {
    const userId = await signedIn(ctx);
    const existing = await ctx.db.query("organisations").first();
    if (existing) {
      const locations = (await ctx.db.query("locations").collect()).filter(item => item.organisationId === existing._id);
      const userMemberships = await ctx.db.query("memberships").withIndex("by_user", (q: any) => q.eq("userId", userId)).collect();
      if (!userMemberships.length && locations[0]) await ctx.db.insert("memberships", { userId, locationId: locations[0]._id, role: "admin" });
      for (const location of locations) await seedLocation(ctx, location._id, userId);
      const products = await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", existing._id)).collect();
      for (const product of products) if (product.name === "Bacon" || product.name === "Hash Browns" || product.name === "Other") await ctx.db.patch(product._id, { active: false });
      if (!products.some(product => product.name === "Chicken Brioche")) await ctx.db.insert("probeProducts", { organisationId: existing._id, name: "Chicken Brioche", minimumTemperature: 76, holdMinutes: 2, locationIds: locations.map(item => item._id), active: true });
      return;
    }
    const organisationId = await ctx.db.insert("organisations", { name: "Le Feast", timezone: "Europe/London" });
    const locationIds: Id<"locations">[] = [];
    for (const [index, store] of stores.entries()) {
      const locationId = await ctx.db.insert("locations", { organisationId, ...store, timezone: "Europe/London", active: true });
      locationIds.push(locationId);
      await ctx.db.insert("memberships", { userId, locationId, role: index === 0 ? "manager" : "admin" });
      await seedLocation(ctx, locationId, userId);
      await ctx.db.insert("scheduledTasks", { locationId, title: "AM Fridge Checks", kind: "temperature", session: "AM", dueLabel: "Due by 10:00", status: index === 1 ? "due" : "complete", completedAt: index === 1 ? undefined : Date.now() - 7200000, completedBy: index === 1 ? undefined : userId });
      await ctx.db.insert("scheduledTasks", { locationId, title: "PM Fridge Checks", kind: "temperature", session: "PM", dueLabel: "Due at close", status: "upcoming" });
      await ctx.db.insert("scheduledTasks", { locationId, title: "Food probe", kind: "probe", dueLabel: "During service", status: "upcoming" });
    }
    for (const name of ["Sausages", "Chicken Brioche"]) await ctx.db.insert("probeProducts", { organisationId, name, minimumTemperature: 76, holdMinutes: 2, locationIds, active: true });
    const equipment = await ctx.db.query("equipment").withIndex("by_location", q => q.eq("locationId", locationIds[0])).collect();
    const roundId = await ctx.db.insert("temperatureRounds", { locationId: locationIds[0], session: "AM", startedAt: Date.now() - 8000000, completedAt: Date.now() - 7800000, createdBy: userId });
    for (const [index, item] of equipment.entries()) await ctx.db.insert("temperatureReadings", { roundId, equipmentId: item._id, locationId: locationIds[0], temperature: [4.2, 3.8, 8.7, 4.6][index], result: index === 2 ? "fail" : "normal", createdAt: Date.now() - 7800000 + index * 30000, createdBy: userId, voided: false });
    await ctx.db.insert("issues", { locationId: locationIds[0], category: "Temperature", title: "Fridge 3 requires action", description: "Recorded at 8.7°C. Le Feast maximum is 8°C.", status: "monitoring", createdAt: Date.now() - 7700000, createdBy: userId, action: "Food moved to another fridge; manager informed." });
    await ctx.db.insert("foodChecks", { locationId: locationIds[0], product: "Sausages", temperature: 81.2, result: "pass", action: "Held for 2 minutes", createdAt: Date.now() - 3500000, createdBy: userId });
    await ctx.db.patch(userId, { role: "admin", name: "Le Feast Operations" });
  },
});

export const dashboard = query({
  args: { locationId: v.optional(v.id("locations")) },
  handler: async (ctx, args) => {
    const userId = await signedIn(ctx);
    const memberships = await ctx.db.query("memberships").withIndex("by_user", q => q.eq("userId", userId)).collect();
    const locationId = args.locationId ?? memberships[0]?.locationId;
    if (!locationId) return null;
    const location = await ctx.db.get(locationId);
    if (!location) return null;
    const equipment = (await ctx.db.query("equipment").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order);
    const tasks = await ctx.db.query("scheduledTasks").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
    const todayKey = localDateKey(Date.now(), location.timezone);
    const rounds = (await ctx.db.query("temperatureRounds").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(round => localDateKey(round.startedAt, location.timezone) === todayKey);
    const readings = (await ctx.db.query("temperatureReadings").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(reading => localDateKey(reading.createdAt, location.timezone) === todayKey);
    const issues = await ctx.db.query("issues").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect();
    const foodChecks = (await ctx.db.query("foodChecks").withIndex("by_location", (q: any) => q.eq("locationId", locationId)).collect()).filter(check => localDateKey(check.createdAt, location.timezone) === todayKey);
    const organisation = await ctx.db.get(location.organisationId);
    const probeProducts = organisation ? (await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", organisation._id)).collect()).filter(product => product.active && product.locationIds.includes(locationId)).sort((a, b) => (a.order ?? 0) - (b.order ?? 0)) : [];
    const openingQuestions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "opening")).collect()).filter(question => question.active);
    const closingQuestions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "closing")).collect()).filter(question => question.active);
    const openingResponses = (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "opening")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey);
    const closingResponses = (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", locationId).eq("checklist", "closing")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey);
    const security = { AM: (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "AM")).collect()).filter(question => question.active).sort((a, b) => a.order - b.order), PM: (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "PM")).collect()).filter(question => question.active).sort((a, b) => a.order - b.order) };
    const securityResponses = { AM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "AM")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey), PM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", locationId).eq("session", "PM")).collect()).filter(response => localDateKey(response.createdAt, location.timezone) === todayKey) };
    const wastageItems = (await ctx.db.query("wastageItems").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(item => item.active).sort((a, b) => a.order - b.order);
    const wastageRecords = (await ctx.db.query("wastageRecords").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(record => localDateKey(record.createdAt, location.timezone) === todayKey);
    const weekday = localWeekday(Date.now(), location.timezone);
    const dateKey = todayKey;
    const cleaningTasks = (await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(task => task.active && (task.frequency === "after_use" || task.frequency === "daily" || (task.frequency === "weekly" && weekday === 1) || (task.frequency === "specific_days" && task.weekdays.includes(weekday)))).sort((a, b) => a.order - b.order);
    const cleaningCompletions = await ctx.db.query("cleaningCompletions").withIndex("by_location_date", q => q.eq("locationId", locationId).eq("dateKey", dateKey)).collect();
    const teamMembers = (await ctx.db.query("teamMembers").withIndex("by_location", q => q.eq("locationId", locationId)).collect()).filter(member => member.active);
    const issueUpdates = await ctx.db.query("issueUpdates").withIndex("by_location", q => q.eq("locationId", locationId)).collect();
    const issuesWithUpdates = await Promise.all(issues.map(async issue => ({ ...issue, createdByName: (await ctx.db.get(issue.createdBy))?.name ?? "Staff member", resolvedByName: issue.resolvedBy ? (await ctx.db.get(issue.resolvedBy))?.name ?? "Manager" : undefined, updates: await Promise.all(issueUpdates.filter(update => update.issueId === issue._id).sort((a, b) => a.createdAt - b.createdAt).map(async update => ({ ...update, createdByName: (await ctx.db.get(update.createdBy))?.name ?? "Staff member" }))) })));
    return { location, equipment, tasks, rounds, readings, issues: issuesWithUpdates, foodChecks, probeProducts, security, securityResponses, wastageItems, wastageRecords, cleaningTasks, cleaningCompletions, teamMembers, checklists: { opening: { questions: openingQuestions.sort((a, b) => a.order - b.order), responses: openingResponses }, closing: { questions: closingQuestions.sort((a, b) => a.order - b.order), responses: closingResponses } }, role: (await ctx.db.get(userId))?.role ?? "staff" };
  },
});

export const team = query({ args: { locationId: v.id("locations") }, handler: async (ctx, args) => { await requireManager(ctx); const members = (await ctx.db.query("teamMembers").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(member => member.active); return { members }; } });
export const addTeamMemberName = mutation({ args: { locationId: v.id("locations"), name: v.string() }, handler: async (ctx, args) => { await requireManager(ctx); return await ctx.db.insert("teamMembers", { locationId: args.locationId, name: args.name.trim(), active: true, createdAt: Date.now() }); } });
export const updateTeamMemberName = mutation({ args: { memberId: v.id("teamMembers"), name: v.string() }, handler: async (ctx, args) => { await requireManager(ctx); await ctx.db.patch(args.memberId, { name: args.name.trim() }); } });
export const deactivateTeamMember = mutation({ args: { memberId: v.id("teamMembers") }, handler: async (ctx, args) => { await requireManager(ctx); await ctx.db.patch(args.memberId, { active: false }); } });
export const addTeamMember = mutation({ args: { locationId: v.id("locations"), email: v.string(), role: v.union(v.literal("staff"), v.literal("manager")) }, handler: async (ctx, args) => { await requireManager(ctx); const user = await ctx.db.query("users").withIndex("email", q => q.eq("email", args.email.trim())).first(); if (!user) throw new Error("No account found for that email"); const existing = (await ctx.db.query("memberships").collect()).find(membership => membership.locationId === args.locationId && membership.userId === user._id); if (existing) { await ctx.db.patch(existing._id, { role: args.role }); return existing._id; } return await ctx.db.insert("memberships", { locationId: args.locationId, userId: user._id, role: args.role }); } });
export const removeTeamMember = mutation({ args: { membershipId: v.id("memberships") }, handler: async (ctx, args) => { await requireManager(ctx); await ctx.db.delete(args.membershipId); } });
export const operations = query({ args: {}, handler: async (ctx) => { const userId = await signedIn(ctx); const user = await ctx.db.get(userId); const memberships = await ctx.db.query("memberships").withIndex("by_user", q => q.eq("userId", userId)).collect(); const canManage = user?.role === "admin" || user?.role === "manager" || memberships.some(membership => membership.role === "admin" || membership.role === "manager"); if (!canManage) throw new Error("Manager access required"); const allLocations = await ctx.db.query("locations").collect(); const locations = user?.role === "admin" || memberships.some(membership => membership.role === "admin") ? allLocations : allLocations.filter(location => memberships.some(membership => membership.locationId === location._id)); const result = []; for (const location of locations) { const tasks = await ctx.db.query("scheduledTasks").withIndex("by_location", q => q.eq("locationId", location._id)).collect(); const issues = await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", location._id)).collect(); result.push({ location, total: tasks.length + 3, complete: tasks.filter(t => t.status === "complete").length, outstanding: tasks.filter(t => t.status !== "complete").length, issues: issues.filter(i => i.status !== "resolved").length, latestIssue: issues.filter(i => i.status !== "resolved").sort((a, b) => b.createdAt - a.createdAt)[0] }); } return result; } });

export const legacyCalendar = query({ args: { locationId: v.id("locations"), monthStart: v.number(), monthEnd: v.number() }, handler: async (ctx, args) => { await signedIn(ctx); const rounds = await ctx.db.query("temperatureRounds").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const readings = await ctx.db.query("temperatureReadings").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const probes = await ctx.db.query("foodChecks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const issues = await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const days: Record<string, { date: string; status: "green" | "amber" | "red"; readings: number; probes: number; issues: number }> = {}; for (const round of rounds) { const time = round.startedAt; if (time < args.monthStart || time > args.monthEnd) continue; const date = new Date(time).toISOString().slice(0, 10); days[date] ??= { date, status: "green", readings: 0, probes: 0, issues: 0 }; days[date].readings += readings.filter(item => item.roundId === round._id).length; } for (const probe of probes) { if (probe.createdAt < args.monthStart || probe.createdAt > args.monthEnd) continue; const date = new Date(probe.createdAt).toISOString().slice(0, 10); days[date] ??= { date, status: "green", readings: 0, probes: 0, issues: 0 }; days[date].probes++; if (probe.result === "fail") days[date].status = "amber"; } for (const issue of issues) { if (issue.createdAt < args.monthStart || issue.createdAt > args.monthEnd) continue; const date = new Date(issue.createdAt).toISOString().slice(0, 10); days[date] ??= { date, status: "green", readings: 0, probes: 0, issues: 0 }; days[date].issues++; if (issue.status !== "resolved") days[date].status = "red"; else if (days[date].status === "green") days[date].status = "amber"; } return Object.values(days); } });

export const calendar = query({
  args: { locationId: v.id("locations"), monthStart: v.number(), monthEnd: v.number() },
  handler: async (ctx, args) => {
    await signedIn(ctx);
    const location = await ctx.db.get(args.locationId);
    if (!location) return [];
    const timezone = location.timezone;
    const todayKey = localDateKey(Date.now(), timezone);
    const equipment = (await ctx.db.query("equipment").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.active);
    const openingQuestions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect()).filter(item => item.active);
    const closingQuestions = (await ctx.db.query("checklistQuestions").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect()).filter(item => item.active);
    const securityQuestions = {
      AM: (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect()).filter(item => item.active),
      PM: (await ctx.db.query("securityQuestions").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect()).filter(item => item.active),
    };
    const organisation = await ctx.db.get(location.organisationId);
    const probeProducts = organisation ? (await ctx.db.query("probeProducts").withIndex("by_organisation", q => q.eq("organisationId", organisation._id)).collect()).filter(item => item.active && item.locationIds.includes(args.locationId)) : [];
    const rounds = await ctx.db.query("temperatureRounds").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const readings = await ctx.db.query("temperatureReadings").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const probes = await ctx.db.query("foodChecks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const openingResponses = await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect();
    const closingResponses = await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect();
    const securityResponses = {
      AM: await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect(),
      PM: await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect(),
    };
    const wastage = await ctx.db.query("wastageRecords").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const cleaningTasks = (await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.active);
    const cleaningCompletions = await ctx.db.query("cleaningCompletions").withIndex("by_location_date", q => q.eq("locationId", args.locationId)).collect();
    const issues = await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect();
    const days: Record<string, { date: string; status: "green" | "amber" | "red" | "grey"; readings: number; probes: number; issues: number }> = {};
    const start = new Date(args.monthStart);
    const end = new Date(args.monthEnd);
    for (let cursor = new Date(start.getFullYear(), start.getMonth(), start.getDate()); cursor <= end; cursor.setDate(cursor.getDate() + 1)) {
      const dateKey = localDateKey(cursor.getTime(), timezone);
      days[dateKey] = { date: dateKey, status: dateKey > todayKey ? "grey" : "red", readings: 0, probes: 0, issues: 0 };
    }
    for (const dateKey of Object.keys(days)) {
      if (dateKey > todayKey) continue;
      const dayRounds = rounds.filter(item => localDateKey(item.startedAt, timezone) === dateKey);
      const dayReadings = readings.filter(item => localDateKey(item.createdAt, timezone) === dateKey && !item.voided);
      const dayProbes = probes.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayOpening = openingResponses.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayClosing = closingResponses.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayAmSecurity = securityResponses.AM.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayPmSecurity = securityResponses.PM.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const dayWastage = wastage.filter(item => localDateKey(item.createdAt, timezone) === dateKey);
      const weekday = localWeekday(new Date(`${dateKey}T12:00:00Z`).getTime(), timezone);
      const dueCleaning = cleaningTasks.filter(task => task.frequency === "after_use" || task.frequency === "daily" || (task.frequency === "weekly" && weekday === 1) || (task.frequency === "specific_days" && task.weekdays.includes(weekday)));
      const dayCleaning = cleaningCompletions.filter(item => item.dateKey === dateKey);
      const dayIssues = issues.filter(issue => localDateKey(issue.createdAt, timezone) === dateKey || (issue.createdAt < new Date(`${dateKey}T23:59:59Z`).getTime() && issue.status !== "resolved"));
      const failed = dayReadings.some(item => item.result === "fail") || dayProbes.some(item => item.result === "fail") || dayOpening.some(item => item.answer === "no") || dayClosing.some(item => item.answer === "no") || dayIssues.some(item => item.status !== "resolved");
      const complete = dayOpening.length >= openingQuestions.length && dayClosing.length >= closingQuestions.length && dayAmSecurity.length >= securityQuestions.AM.length && dayPmSecurity.length >= securityQuestions.PM.length && ["AM", "PM"].every(session => { const round = dayRounds.find(item => item.session === session && item.completedAt); return !!round && dayReadings.filter(reading => reading.roundId === round._id).length >= equipment.length; }) && (probeProducts.length === 0 || probeProducts.every(product => dayProbes.some(probe => probe.product === product.name))) && dayWastage.length > 0 && dayCleaning.length >= dueCleaning.length;
      const day = days[dateKey];
      day.readings = dayReadings.length;
      day.probes = dayProbes.length;
      day.issues = dayIssues.length;
      day.status = complete ? (failed ? "amber" : "green") : "red";
    }
    return Object.values(days);
  },
});

export const archive = query({ args: { locationId: v.id("locations"), start: v.number(), end: v.number() }, handler: async (ctx, args) => { await signedIn(ctx); const readings = (await ctx.db.query("temperatureReadings").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); const rounds = await ctx.db.query("temperatureRounds").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const probes = (await ctx.db.query("foodChecks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); const issues = (await ctx.db.query("issues").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); const issueUpdates = await ctx.db.query("issueUpdates").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const issuesWithUpdates = await Promise.all(issues.map(async issue => ({ ...issue, createdByName: (await ctx.db.get(issue.createdBy))?.name ?? "Staff member", resolvedByName: issue.resolvedBy ? (await ctx.db.get(issue.resolvedBy))?.name ?? "Manager" : undefined, updates: await Promise.all(issueUpdates.filter(update => update.issueId === issue._id).sort((a, b) => a.createdAt - b.createdAt).map(async update => ({ ...update, createdByName: (await ctx.db.get(update.createdBy))?.name ?? "Staff member" }))) }))); const location = await ctx.db.get(args.locationId); const timezone = location?.timezone ?? "Europe/London"; const questions = { opening: (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "opening")).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end), closing: (await ctx.db.query("checklistResponses").withIndex("by_location_checklist", q => q.eq("locationId", args.locationId).eq("checklist", "closing")).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end) }; const securityResponses = { AM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "AM")).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end), PM: (await ctx.db.query("securityResponses").withIndex("by_location_session", q => q.eq("locationId", args.locationId).eq("session", "PM")).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end) }; const cleaningTasks = (await ctx.db.query("cleaningTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(task => task.active); const cleaningCompletions = (await Promise.all(cleaningTasks.map(task => ctx.db.query("cleaningCompletions").withIndex("by_task", q => q.eq("taskId", task._id)).collect()))).flat().filter(item => item.completedAt >= args.start && item.completedAt <= args.end); const wastageRecords = (await ctx.db.query("wastageRecords").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect()).filter(item => item.createdAt >= args.start && item.createdAt <= args.end); return { readings, rounds: rounds.filter(round => round.startedAt >= args.start && round.startedAt <= args.end), probes, issues: issuesWithUpdates, questions, securityResponses, wastageRecords, cleaningTasks, cleaningCompletions }; } });

export const startRound = mutation({ args: { locationId: v.id("locations"), session: v.union(v.literal("AM"), v.literal("PM")), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); return await ctx.db.insert("temperatureRounds", { ...args, startedAt: Date.now(), createdBy: userId }); } });
export const recordTemperature = mutation({ args: { roundId: v.id("temperatureRounds"), locationId: v.id("locations"), equipmentId: v.id("equipment"), temperature: v.number(), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); const equipment = await ctx.db.get(args.equipmentId); const preferred = equipment?.preferredTemperature ?? 5; const maximum = equipment?.maximumTemperature ?? 8; const result = args.temperature > maximum ? "fail" : args.temperature > preferred ? "within_limit" : "normal"; const readingId = await ctx.db.insert("temperatureReadings", { ...args, result, createdAt: Date.now(), createdBy: userId, voided: false }); let issueId = null; if (result === "fail") { issueId = await ctx.db.insert("issues", { locationId: args.locationId, category: "Temperature", title: `${equipment?.name ?? "Fridge"} requires action`, description: `Recorded at ${args.temperature}°C. The configured maximum is ${maximum}°C.`, originalReading: `${args.temperature}°C`, status: "open", createdAt: Date.now(), createdBy: userId, teamMemberId: args.teamMemberId }); } return { readingId, issueId }; } });
export const completeRound = mutation({ args: { roundId: v.id("temperatureRounds"), locationId: v.id("locations"), session: v.union(v.literal("AM"), v.literal("PM")), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); await ctx.db.patch(args.roundId, { completedAt: Date.now(), ...(args.teamMemberId ? { teamMemberId: args.teamMemberId } : {}) }); const tasks = await ctx.db.query("scheduledTasks").withIndex("by_location", q => q.eq("locationId", args.locationId)).collect(); const sessionTask = tasks.find(item => item.session === args.session); if (sessionTask) await ctx.db.patch(sessionTask._id, { status: "complete", completedAt: Date.now(), completedBy: userId }); await ctx.db.insert("auditEvents", { locationId: args.locationId, userId, type: "temperature_round_completed", detail: `${args.session} temperature round completed`, createdAt: Date.now() }); } });
export const recordFoodCheck = mutation({ args: { locationId: v.id("locations"), product: v.string(), quantity: v.optional(v.string()), temperature: v.number(), action: v.optional(v.string()), teamMemberId: v.optional(v.id("teamMembers")) }, handler: async (ctx, args) => { const userId = await signedIn(ctx); if (!args.quantity?.trim()) throw new Error("Quantity is required"); const now = Date.now(); const result = args.temperature >= 76 ? "pass" : "fail"; const checkId = await ctx.db.insert("foodChecks", { ...args, result, createdAt: now, createdBy: userId }); if (result === "fail") { const issueId = await ctx.db.insert("issues", { locationId: args.locationId, category: "Probe", title: `${args.product} probe below minimum`, description: `Recorded at ${args.temperature}°C for quantity ${args.quantity}.`, originalReading: `${args.temperature}°C`, status: "open", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId, action: args.action }); if (args.action?.trim()) await ctx.db.insert("issueUpdates", { issueId, locationId: args.locationId, updateType: "immediate_action", note: args.action.trim(), status: "monitoring", createdAt: now, createdBy: userId, teamMemberId: args.teamMemberId }); } return checkId; } });
